from decimal import Decimal


def line_total(lines):
    x = 0
    for line in lines:
        x += line["quantity"] * line["unit_cents"]
    return x


def tax_for(amount_cents, rate):
    """Tax in integer cents on amount_cents, rounded half-even.

    rate is a fraction (e.g. Decimal("0.0825") for 8.25%); pass a Decimal or
    string rather than a float to avoid binary rounding error.
    """
    tax = Decimal(amount_cents) * Decimal(str(rate))
    return int(tax.quantize(Decimal(1), rounding=ROUND_HALF_EVEN))
